"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0961-10-15:0":{"b": ["Abdurrahman III morreu em Córdova (2 Ramazan 350); o califado passou para Hakem II.", "16c7e725"], "d": ["Abdurrahman III morreu em Córdova (2 Ramazan 350); o califado passou para Hakem II.", "16c7e725"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0972-01-01:0":{"b": ["O califa fatímida Muiz fez de Bulukkîn governador do Magrebe e instalou-o em Cairuão; começou o período dos Ziridas", "562089c8"], "d": ["O califa fatímida Muiz-Lidînillâh nomeou Bulukkîn b. Zîrî governador do Magrebe e instalou-o em Cairuão (361/972) e deixou a região transferindo o centro administrativo do Estado para o Egito.", "26bbc5b2"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0976-10-02:0":{"b": ["Após a morte de Hakem II, Hişâm II, de onze ou doze anos, tornou-se califa.", "359fba92"], "d": ["Após a morte de Hakem II, Hişâm II, de onze ou doze anos, tornou-se califa.", "359fba92"]},
