"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1107-06-01:0":{"b": ["Sürhâb b. Bedr morre (Şevval de 500 / junho de 1107); sucede-lhe Ebû Mansûr.", "a1931e53"], "d": ["Sürhâb b. Bedr morre (Şevval de 500 / junho de 1107); sucede-lhe Ebû Mansûr.", "a1931e53"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1109-07-31:0":{"b": ["O vizir Ahmed b. Nizâmülmülk foi enviado a Alamut com um grande exército; por causa do inverno, não se obteve resultado", "ba5263e5"], "d": ["O sultão seljúcida Muhammed Tapar enviou contra Alamut, com um grande exército, o vizir Ahmed b. Nizâmülmülk para eliminar Hasan Sabbâh; a campanha ficou sem resultado devido ao inverno. O verdadeiro cerco viria em 1117.", "2e2a9c88"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1113-06-18:0":{"b": ["Em Alepo foram mortos os representantes de Hasan Sabbâh na Síria e grande número de batiníes", "c70cc81f"], "d": ["O sultão seljúcida Muhammed Tapar pediu a Alparslan el-Ahras, melik de Alepo, e a Saîd b. Bedî‘, Reîsülahdâs, que matassem os batiníes da cidade; foram mortos grande número de batiníes, entre eles os representantes de Hasan Sabbâh na Síria, como Ebû Tâhir es-Sâiğ, İsmâil ed-Dâî e o irmão de Hakîm el-Müneccim (507/1113).", "c7adbffa"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1117-01-01:0":{"b": ["A dinastia annâzida chegou ao fim (segundo o registo de 130 anos de Ibn al-Athir)", "a533a1d6"], "d": ["A dinastia annâzida chegou ao fim (segundo o registo de 130 anos de Ibn al-Athir)", "a533a1d6"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1124-05-23:0":{"b": ["Hasan Sabbâh morreu em Alamut", "1dccca4f"], "d": ["Hasan Sabbâh morreu em Alamut", "1dccca4f"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1127-01-17:0":{"b": ["O sultão Sencer cercou Alamut; a fortaleza não foi tomada", "6b06eb0c"], "d": ["O sultão seljúcida Sencer cercou em 521 (1127) Alamut, centro dos ismaelitas nizaritas; não foi possível conquistar a fortaleza.", "91215716"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1130-01-01:0":{"b": ["O sultão Mahmûd b. Muhammed Tapar cercou Alamut; a fortaleza não foi tomada", "64d6b833"], "d": ["O sultão seljúcida Mahmûd b. Muhammed Tapar cercou Alamut em 524 (1130); a fortaleza não caiu.", "791399dc"]},
